// ============================================================================
//  shopflow storefront-admin router  (LEGACY, ported from the 2017 Express app)
// ----------------------------------------------------------------------------
//  route(request) -> response, no I/O: the admin UI and the nightly report job
//  both call it in-process. request = { method, url, headers, body };
//  response = { status, headers, body }.
//
//  Known quirks that the admin UI relies on (DO NOT "fix" without a ticket):
//   - page/per_page are read with parseInt, so "2abc" is page 2; per_page=0 is
//     the default (20), anything above 50 is 50.
//   - promo codes are matched case-insensitively but NOT trimmed.
//   - sort=name is case-sensitive (uppercase names first).
//   - a shipping weight of 0 (or missing) is billed as 500 g.
//   - dates in reports are not checked against month length (2025-02-31 is ok
//     and simply matches nothing).
//   - CSV exports end with a trailing newline and use ";" for VND decimals.
//
//  Do not add new routes here; new endpoints go to web-js/src.
// ============================================================================

